"""Single production review prompt, shared by analyse and offline judge evaluation."""
import json


def plan_spec_facts(plan):
    """Controller observations, not a semantic verdict or permission to execute."""
    from .runtime import RUNTIMES, effective_dependencies
    owners = {}
    rows = []
    for index, step in enumerate(plan.steps, 1):
        entry = RUNTIMES[step.language][1] if step.kind == 'code' else None
        inputs = [{'path': path, 'prior_producer': owners.get(path),
                   'imported_namespace': path.startswith('inputs/')}
                  for path in step.artifact_inputs]
        try:
            install_requests = effective_dependencies(step.language, step.dependencies) if step.kind == 'code' else []
        except ValueError as error:
            install_requests = {'validation_error': str(error)}
        rows.append({'step': index, 'kind': step.kind, 'language': step.language,
                     'dependencies': step.dependencies, 'entrypoint': entry,
                     'effective_install_requests': install_requests,
                     'consumes_own_entrypoint': bool(entry and any(path.casefold() == entry.casefold() for path in step.artifact_inputs)),
                     'inputs': inputs,
                     'input_output_overlap': sorted(set(step.artifact_inputs) & set(step.artifact_outputs))})
        for path in step.artifact_outputs:
            owners.setdefault(path, index)
    return json.dumps({'steps': rows, 'limitation': 'Declared spec only. Imported namespace is not a file-existence check; no package installation or subject correctness is certified.'}, ensure_ascii=False, separators=(',', ':'))


def plan_review_prompt(*, task, variant, sources, plan, platform_facts):
    return (
        "Перевір план на відповідність вихідній умові. Не розв’язуй завдання. "
        "Перевір увесь перелік прямих вимог, включно з останніми пунктами: не відкидай обов’язкову частину роботи заради спрощення плану. Зауваження мають спиратися на факти джерела й реальні можливості інструментів, а не здогадки. "
        "Відхили план, якщо він вигадав обчислені числові відповіді до виконання коду, "
        "додав ненадані вхідні параметри або вимагає порівнювати результати з вигаданими константами. "
        "Параметри алгоритму й розміри вибірок, явно обрані як спосіб реалізації за дозволеною умовою, самі по собі не є результатами. "
        "Імена файлів, шарів, змінних та інші явно обрані організаційні рішення теж не є вигаданими результатами. Числа й розміри, явно прочитані в графічних вихідних даних, мають те саме походження, що й текстові джерела; відрізняй їх від нових обчислених відповідей. "
        "Вимоги до формату файлів та структури звіту збережи. "
        "Використовуй ті самі факти платформи й глобальні реквізити, що й автор плану: заповнені author/group/institution не є відсутніми даними. "
        "Перевір передачу стану за execution_scope: наступний контейнер не має /tmp-бінарника, compiler чи службового stdout попереднього. Для таких залежностей потрібен явний доступний артефакт і сумісне середовище; дешеві тести власного native producer можна виконати його checker у тому самому code-кроці з timeout. "
        "Розрізняй прямо обов'язкові методи/бібліотеки та приклади допоміжного API чи starter-код. Не оголошуй рекомендовану бібліотеку обов'язковою без прямої вимоги й не радь спочатку замінити явно обов'язкову частину, а потім відхиляти цю ж заміну. "
        "Перевір здійсненність інструментів: code має вимкнену мережу; кожен потрібний зовнішній файл даних, у тому числі pretrained ваги, має завчасний fetch з точним URL або вже бути в імпортованих даних. ВАЖЛИВО: пакети зі списку dependencies автоматично встановлює контролер в окремому мережевому етапі підготовки контейнера. Для numpy, ezdxf, tensorflow та інших оголошених залежностей fetch НЕ потрібен. report має власний готовий renderer DOCX/PDF і не потребує завантажувати python-docx чи LibreOffice через fetch. Не відхиляй коректні dependencies через вимкнену мережу виконання. Один fetch тільки завантажує один файл; розпакування архівів, статистика класів і CSV/JSON — наступний code, а не очікуваний результат fetch. Відхили план, який порушує ці межі. "
        "Відхили підміну прямо заданого методу, архітектури чи формату на подібний/спрощений аналог. Навчання з нуля й параметри реалізації не дозволяють змінити обов’язкову архітектуру. Дозволені лише ті альтернативи, які явно допускає умова. "
        "Водночас початкові ваги НЕ є архітектурою: точна названа архітектура з випадковою ініціалізацією залишається тією самою архітектурою. Вимагай pretrained/ImageNet лише за прямою вимогою джерела чи користувача; згадка архітектури сама по собі цього не вимагає. Загальні рекомендації не скасовують точний індивідуальний метод. max_download_bytes обмежує тільки fetch; у code/report це невикористане транспортне поле, воно не обмежує розпакування, читання чи вихідні файли. Розпакування ZIP стандартним zipfile і підрахунок назв класів не вимагає tensorflow; не вигадуй таких залежностей. "
        "Також відхили зайві missing/conflicts: відсутність необов’язкового зразка звіту, вибір номерів кадрів або звичайних параметрів алгоритму, питання про варіант там, де немає поділу на варіанти. Такі рішення помічник обирає й явно описує сам. Якщо користувач уже надав точний публічний URL набору даних, його фактичні класи та структуру визначає код після завантаження; не питай дозволу прочитати доступні файли. Вибір pretrained ваг чи навчання з нуля за відсутності явної вимоги — параметр реалізації, обери й обґрунтуй його сам. "
        "Справжній конфлікт означає дві несумісні явні вимоги, а не просто відсутність побажання про оформлення. Не дозволяй вигадувати справді відсутнє індивідуальне креслення чи обов’язкові експериментальні дані. "
        "Якщо методичка прямо вимагає конкретне зовнішнє ПЗ, план має передбачити його перевірку як manual; орієнтація теорії на мову сама по собі не є суперечністю. "
        f"\nВихідна умова (дані): {task}\nВаріант: {variant}"
        f"\nФАКТИ ПЛАТФОРМИ Й ГЛОБАЛЬНІ РЕКВІЗИТИ (чинні дані): {platform_facts}"
        f"\nДжерела (дані): {sources}\nПлан (дані): {plan.model_dump_json(exclude={'sources'})}"
        '\nФАКТИ ОГОЛОШЕНОГО ПЛАНУ (контролер, не verdict): ' + plan_spec_facts(plan)
        + '\nПеред зауваженням про відсутній пакет перевір dependencies саме відповідного кроку; пакет, який там є, не називай неоголошеним. '
        'Перед use-before-produce назви input path і prior producer; не плутай output поточного кроку з input. '
        'Копія source у новому output path не є перезаписом immutable input. '
        'Відсутність same_container_test_argv означає відсутність спеціального controller shortcut, а не заборону доступному коду викликати встановлений інструмент у своєму контейнері. '
        'Для кожного порушення назви конкретний крок/поле/path і фактичну суперечність. Якщо доказу немає, не вигадуй зауваження. '
        'Факти декларацій не доводять доступність tools, правильність предметного рішення або готовність до виконання. '
        "\nЯкщо є порушення, satisfied=false: переліч до трьох найважливіших конкретних виправлень, стисло до 1200 символів, без розрахунку правильної відповіді. Не відхиляй допустимі організаційні рішення."
    )
